    for (let i = 0; i < del.length; i += 100) await env.DB.batch(del.slice(i, i + 100).map((id) => env.DB.prepare("UPDATE docs SET data = '{}', deleted = 1, updated = ? WHERE col = ? AND id = ?").bind(updated, col, id)));
